const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s).replace(/_/g,'').toLowerCase();
const original=`https://qianchuan.jinritemai.com/overall-prom?aavid=${ACCOUNT_ID}#?marGoal=1&overallPromViewTab=product&uniVideoTab=1`;
$('.original-link').href=original;
const dateParts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));
const today=`${dateParts.year}-${dateParts.month}-${dateParts.day}`;
$('#date-from').value=today;$('#date-to').value=today;$('#date-from').max=today;$('#date-to').max=today;
let configs={top:TOP_METRIC_CONFIG,table:TABLE_METRIC_CONFIG},loadedConfig=false,selectedTop=[],selectedTable=[];
let model={source:'none',plans:[],metrics:[],total:0,totals:{metrics:{}}};
let query={accountId:ACCOUNT_ID,page:1,pageSize:10,product:'selected',search:'',searchOption:1,status:'all',sortField:'create_time',sortType:'desc'};
let selectedPlans=new Set(),busy=false,toastTimer,lastCycleSeen=null,monitorTick,rangeMode="today",rangeDraftDirty=false,appliedRange=datePreset("today");
$('#search-type').innerHTML='<option value="all">计划</option>';
$('#status').innerHTML='<option value="all">请筛选计划状态</option>'+[[13,'投放中'],[2,'新建审核中'],[15,'修改审核中'],[16,'审核不通过'],[4,'手动暂停'],[11,'计划预算不足'],[22,'账户预算已花光'],[10,'账户余额不足'],[23,'系统暂停'],[14,'不在投放时段'],[6,'未到投放时间'],[24,'在投计划配额超限'],[19,'商品暂不可用'],[1,'已删除'],[3,'已完成'],[30,'全部（包含已删除）'],[21,'已终止']].map(([v,n])=>`<option value="${v}">${n}</option>`).join('');
$('#service').innerHTML='<option value="all">选择营销服务项</option><option value="3">基础投放</option><option value="1">千川星选素材投放</option><option value="2">含达人佣金出价</option>';
const storage=side=>`qianchuan:${ACCOUNT_ID}:${side}-selection:v3`;
function selection(side){const c=configs[side];try{migratePreferences(localStorage,storage(side),side==='top'?TOP_METRIC_CONFIG:TABLE_METRIC_CONFIG,c);const saved=JSON.parse(localStorage.getItem(storage(side)));if(Array.isArray(saved))return validateMetricSelection(c,saved);}catch{}return [...c.selected];}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function metricValue(metrics,key){const m=metrics?.[normalize(key)]||metrics?.[key];return m?{value:m.Value??m.value,text:m.ValueStr??m.valueStr??'-'}:null;}
function chart(points){const valid=points.filter(p=>Number.isFinite(p.value));if(valid.length<2)return '';const vals=valid.map(p=>p.value),lo=Math.min(...vals),hi=Math.max(...vals);const d=valid.map((p,i)=>`${i?'L':'M'}${2+i*96/(valid.length-1)} ${27-(hi===lo?12:(p.value-lo)*24/(hi-lo))}`).join(' ');return `<svg class="spark" viewBox="0 0 100 30" role="img" aria-label="真实数据趋势"><path d="${d}" fill="none" stroke="currentColor" stroke-width="2"/></svg>`;}
function renderMetrics(){const keys=loadedConfig?selectedTop:configs.top.selected;$('#metrics').innerHTML=keys.map(key=>{const def=configs.top.metrics.find(m=>m.key===key),value=model.metrics.find(m=>m.key===key);return `<article class="metric"><h2>${esc(def?.label||key)}</h2>${value?chart(value.trend||[]):''}<strong>${esc(value?.value??'—')}</strong><span class="change ${String(value?.change).startsWith('+')?'positive':''}">${esc(value?.change??'')}</span></article>`;}).join('');}
function dataCells(plan,showBasis=true){return `<td data-col="create_time" class="plan-created-time">${showBasis?esc(formatPlanCreatedAt(plan)):"—"}</td>`+selectedTable.map(key=>{const v=metricValue(plan.metrics,key),base=showBasis?metricValue(plan.metrics,key+'_primary'):null;return `<td data-col="${esc(key)}">${esc(v?.text??'-')}${base?`<div class="subtle">基础 ${esc(base.text)}</div>`:''}</td>`;}).join('');}
function renderTable(){
 const head=$('thead tr');head.querySelectorAll('[data-col]').forEach(e=>e.remove());
 head.insertAdjacentHTML('beforeend',`<th data-col="create_time" aria-sort="${query.sortField==='create_time'?(query.sortType==='asc'?'ascending':'descending'):'none'}"><button data-sort="create_time" title="计划真实创建时间（北京时间）">创建时间 ${query.sortField==='create_time'?(query.sortType==='asc'?'↑':'↓'):'↕'}</button></th>`+selectedTable.map(key=>{const m=configs.table.metrics.find(m=>m.key===key);return `<th data-col="${esc(key)}" aria-sort="${query.sortField===key?(query.sortType==='asc'?'ascending':'descending'):'none'}"><button data-sort="${esc(key)}">${esc((m?.label||key)+(/金额|成本|消耗|佣金/.test(m?.label||'')&&!/率/.test(m?.label||'')?'(元)':''))} ${query.sortField===key?(query.sortType==='asc'?'↑':'↓'):'↕'}</button></th>`;}).join(''));
 const rows=model.plans,hasData=model.source!=='none';
 $('#table-body').innerHTML=(hasData?`<tr class="total-row"><td></td><td colspan="7">全部 ${model.accountTotal??model.total} 条计划汇总</td>${dataCells(model.totals,false)}</tr>`:'')+(rows.length?rows.map(p=>`<tr class="${p.newEvent?'plan-new-row':''}"><td><input type="checkbox" data-select="${esc(p.id)}" aria-label="选择计划 ${esc(p.name)}" ${selectedPlans.has(p.id)?'checked':''}></td><td><div class="plan-content"><button type="button" class="switch ${p.isEnabled?'enabled':''}" data-action="status" data-plan="${esc(p.id)}" role="switch" aria-checked="${p.isEnabled}" aria-label="切换计划 ${esc(p.name)} 的状态"></button><div><button class="plan-name" data-action="detail" data-plan="${esc(p.id)}">${esc(p.name)}</button>${p.newEvent?`<span class="new-plan-badge ${p.newEvent.kind==='created'?'':'discovered-badge'}" title="${esc('发现于 '+p.newEvent.detectedAt)}">${p.newEvent.kind==='created'?'新计划':'首次发现'}</span>`:''}<div class="plan-id">ID：${esc(p.id)}</div><div class="plan-meta"><button data-action="product" data-plan="${esc(p.id)}">商品 ›</button><button data-action="aweme" data-plan="${esc(p.id)}">抖音号 ›</button><button data-action="material" data-plan="${esc(p.id)}">素材 ›</button><button data-action="edit" data-plan="${esc(p.id)}">操作 ›</button></div><div class="quick-plan-actions"><button data-action="boost-create" data-plan="${esc(p.id)}">一键起量</button><button data-action="heat-create" data-plan="${esc(p.id)}">素材追投</button></div></div></div></td><td><span class="status-dot ${p.status==='active'?'green':''}"></span>${esc(p.statusText)}</td><td class="plan-description">每日预算 <button class="link" data-action="budget" data-plan="${esc(p.id)}">${esc(p.budget)}元</button><br>综合营销ROI目标 <button class="link" data-action="roi" data-plan="${esc(p.id)}">${p.roiTarget==null?'-':Number(p.roiTarget).toFixed(2)}</button></td><td>${esc(p.service)}</td><td class="stack"><button data-action="boost" data-plan="${esc(p.id)}">一键起量</button><button data-action="heat" data-plan="${esc(p.id)}">素材追投</button><button data-action="search" data-plan="${esc(p.id)}">搜索抢首屏</button></td><td class="stack"><button data-action="edit" data-plan="${esc(p.id)}">编辑</button><button data-action="log" data-plan="${esc(p.id)}">日志</button><button data-action="delete" data-plan="${esc(p.id)}">删除</button></td><td>乘方投放</td>${dataCells(p)}</tr>`).join(''):`<tr><td colspan="${9+selectedTable.length}" class="empty-cell">${hasData?'暂无匹配的计划':'连接千川浏览器后显示真实数据'}</td></tr>`);
 $('#row-count').textContent=hasData?`筛选 ${model.total} 条 · 已采集 ${model.cachedCount??model.plans.length} / ${model.accountTotal??model.total} 条 · 本页 ${rows.length} 条`:'尚未读取真实数据';$('#selected-count').textContent=selectedPlans.size?`已选择 ${selectedPlans.size} 条`:'';
 $('#select-all').checked=rows.length>0&&rows.every(p=>selectedPlans.has(p.id));$('#select-all').indeterminate=rows.some(p=>selectedPlans.has(p.id))&&!$('#select-all').checked;
 renderPager();applyTableView();
}
function renderPager(){const pages=Math.max(1,Math.ceil(model.total/query.pageSize));$('#pagination').innerHTML=`<button data-page="${query.page-1}" ${query.page<=1||busy?'disabled':''}>上一页</button><span>第 ${query.page} / ${pages} 页</span><button data-page="${query.page+1}" ${query.page>=pages||busy?'disabled':''}>下一页</button><label>每页 <select id="page-size" aria-label="每页条数">${[10,20,50,100].map(n=>`<option ${query.pageSize===n?'selected':''}>${n}</option>`).join('')}</select> 条</label><label>跳至 <input id="page-jump" type="number" min="1" max="${pages}" value="${query.page}" aria-label="跳转页码"></label><button id="jump">跳转</button>`;}
function openDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
function metricDialog(side){if(!loadedConfig){toast('请先连接浏览器，读取真实指标配置');return;}openMetricPicker({config:configs[side],selected:side==='top'?selectedTop:selectedTable,storageKey:storage(side),notify:toast,onApply(keys){if(side==='top')selectedTop=keys;else selectedTable=keys;localStorage.setItem(storage(side),JSON.stringify(keys));renderMetrics();renderTable();poller.invalidate();}});}
async function pairingDialog(){const r=await fetch('/api/pairing'),c=await r.json();openDialog('连接千川浏览器',`<p>在 Chrome 中登录账户 <b>${ACCOUNT_ID}</b> 并保持“推商品”页面打开。</p><p>加载交付包里的 <code>bridge-extension</code> 扩展后，将以下本机地址和连接码填入扩展。</p><label>本机地址<input readonly value="${esc(c.url)}"></label><label>连接码<input readonly value="${esc(c.token)}" autocomplete="off"></label><p>登录凭据始终留在千川页面。连接后关闭本窗口并点击刷新。</p>`);}
async function planAction(action,id){const p=model.plans.find(p=>p.id===id);if(!p)return;
 if(['budget','roi','status','delete','edit','boost-create','heat-create'].includes(action)&&!await ensureOperator())return;
 if(action!=='edit'&&$('#dialog').open)$('#dialog').close();
 if(['budget','roi','status','delete'].includes(action))return openPlanOperation(p,action,{notify:toast,allowWrites:operatorEnabled(),onSuccess:()=>poller.invalidate()});
 if(['boost-create','heat-create'].includes(action))return openTaskForm(p,{kind:action==='boost-create'?'boost':'heat',notify:toast,allowWrites:operatorEnabled(),onSuccess:()=>poller.invalidate()});
 if(action==='edit')return openDialog('编辑计划',`<p><b>${esc(p.name)}</b><br>ID：${esc(p.id)}</p><button type="button" class="primary" data-action="budget" data-plan="${esc(p.id)}">编辑预算</button> <button type="button" class="primary" data-action="roi" data-plan="${esc(p.id)}">编辑ROI目标</button> <button type="button" data-action="status" data-plan="${esc(p.id)}">${p.isEnabled?'暂停投放':'启动投放'}</button> <button type="button" data-action="boost" data-plan="${esc(p.id)}">一键起量</button> <button type="button" data-action="heat" data-plan="${esc(p.id)}">素材追投</button> <button type="button" data-action="search" data-plan="${esc(p.id)}">搜索抢首屏</button> <button type="button" data-action="log" data-plan="${esc(p.id)}">操作日志</button> <button type="button" data-action="delete" data-plan="${esc(p.id)}">删除计划</button>`);
 openPlanDetail(p,{from:model.from,to:model.to,tab:action==='detail'?'data':['boost','heat','search'].includes(action)?'control':action,controlType:['boost','heat','search'].includes(action)?action:'boost',notify:toast,onAction:planAction,allowWrites:operatorEnabled()});
}
const poller=createPoller({load:loadLanData,interval:15000,
 query:()=>({...query,...getAppliedRange(),...(loadedConfig?{topMetrics:selectedTop,tableMetrics:selectedTable}:{})}),
 onLoading(value){busy=value;showRangeLoading(value);$('#refresh').disabled=value;$('#refresh').classList.toggle('loading',value);if(value&&model.source==='none')$('#source-status').textContent='正在读取采集结果…';renderPager();},
 onData(data){window.QCHealth?.ready(data.fetchedAt);const first=!loadedConfig;configs={top:data.topConfig,table:data.tableConfig};if(first){selectedTop=selection('top');selectedTable=selection('table');loadedConfig=true;}model=data;query.page=data.page;renderMonitor();renderMetrics();renderTable();$('#source-status').textContent=`账户 ${ACCOUNT_ID} · ${data.complete?'真实接口 · 完整采集':'待补齐的历史样本'} · ${data.allowWrites?'已允许真实操作':'只读模式'} · 数据日期 ${data.from} 至 ${data.to}`;$('#updated').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(data.fetchedAt))+' 更新';$('#last-success').textContent=data.fetchedAt;$('#last-success').dataset.timestamp=data.fetchedAt;updateInterfaceStatus(data);showAppliedRange(data);if(first&&(JSON.stringify(selectedTop)!==JSON.stringify(configs.top.selected)||JSON.stringify(selectedTable)!==JSON.stringify(configs.table.selected)))queueMicrotask(()=>poller.invalidate());},
 onError(error){window.QCHealth?.failure('snapshot','network');showInterfaceError(error);const prefix=model.source==='none'?'尚未取得数据':'更新失败，已保留上次数据';$('#source-status').textContent=prefix+' · '+(error.code==='AUTH_REQUIRED'?'登录失效，请在原千川页重新登录':error.message);},
});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.closest('.plan-drawer,.operation-dialog,.metric-picker'))return;
 if(b.dataset.sort){query.sortType=query.sortField===b.dataset.sort&&query.sortType==='desc'?'asc':'desc';query.sortField=b.dataset.sort;query.page=1;poller.invalidate();}
 if(b.dataset.page){query.page=Math.max(1,Number(b.dataset.page));poller.invalidate();}
 if(b.dataset.product){query.product=b.dataset.product==='托管'?'managed':'selected';query.page=1;$$('[data-product]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-selected',String(t===b));});poller.invalidate();}
 if(b.dataset.action){e.preventDefault();void planAction(b.dataset.action,b.dataset.plan);}
 if(b.id==='jump'){query.page=Math.max(1,Math.min(Math.max(1,Math.ceil(model.total/query.pageSize)),Number($('#page-jump').value)||1));poller.invalidate();}
});
document.addEventListener('change',e=>{if(e.target.dataset.select){e.target.checked?selectedPlans.add(e.target.dataset.select):selectedPlans.delete(e.target.dataset.select);renderTable();}if(e.target.id==='page-size'){query.pageSize=Number(e.target.value);query.page=1;poller.invalidate();}});
function search(){query.search=$('#search').value.trim();query.searchOption=1;query.page=1;poller.invalidate();}
$('#search').addEventListener('keydown',e=>{if(e.key==='Enter')search();});$('#search-button').onclick=search;
$('#status').onchange=()=>{query.status=$('#status').value;query.page=1;poller.invalidate();};
$('#service').onchange=()=>{query.service=$('#service').value;query.page=1;poller.invalidate();};
$('#select-all').onchange=e=>{model.plans.forEach(p=>e.target.checked?selectedPlans.add(p.id):selectedPlans.delete(p.id));renderTable();};
$('#columns').onclick=()=>metricDialog('top');$('#table-columns').onclick=()=>metricDialog('table');
$('#close-recommendations').onclick=()=>$('#recommendations').hidden=true;
$('#reset').onclick=()=>{$('#search').value='';$('#status').value='all';$('#service').value='all';query={...query,page:1,search:'',status:'all',service:'all',serviceMode:'include',costStatus:'all',sortField:'create_time',sortType:'desc',onlyNew:false};selectedPlans.clear();poller.invalidate();};
for(const id of ['date-from','date-to'])$('#'+id).onchange=()=>{if($('#date-from').value>$('#date-to').value){toast('开始日期不能晚于结束日期');return;}query.page=1;poller.invalidate();};
$('#refresh').onclick=()=>{query.force=true;void poller.refresh().finally(()=>query.force=false);};$('#bridge-connect').onclick=()=>toast('请在采集电脑打开 http://127.0.0.1:5173/connect.html');
$('#new-plan').onclick=()=>{query.onlyNew=!query.onlyNew;query.page=1;renderMonitor();poller.invalidate();};
$('#more-filters').onclick=()=>{openDialog('更多筛选',`<label>消耗情况<select id="cost-filter"><option value="all">全部</option><option value="nonzero">有消耗</option><option value="zero">无消耗</option></select></label><label>营销服务筛选<select id="service-mode"><option value="include">包含</option><option value="exclude">不包含</option></select></label><button type="button" id="apply-extra" class="primary">应用筛选</button>`);$('#cost-filter').value=query.costStatus||'all';$('#service-mode').value=query.serviceMode||'include';$('#apply-extra').onclick=()=>{query.costStatus=$('#cost-filter').value;query.serviceMode=$('#service-mode').value;query.page=1;$('#dialog').close();poller.invalidate();};};
$('#fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();
document.addEventListener('visibilitychange',()=>{if(!document.hidden)void poller.refresh();});
window.addEventListener('pagehide',()=>{poller.stop();clearInterval(monitorTick);});window.addEventListener('pageshow',()=>{poller.start();clearInterval(monitorTick);monitorTick=setInterval(renderCountdown,1000);});
$('#updated').textContent='尚未更新';$('#balance').textContent='—';
$('#new-plan').textContent='只看新增';$('#refresh').title='刷新显示（相同日期区间共用5分钟缓存）';initializeDateRange();document.querySelector('.refresh-cycle').textContent='服务每5分钟采集 · 页面自动同步';initializeLanInterface();initializeOperator(toast);renderMetrics();renderTable();poller.start();monitorTick=setInterval(renderCountdown,1000);

function renderCountdown(){const next=Date.parse(model.monitor?.nextCaptureAt||'');const remaining=Math.max(0,Math.ceil((next-Date.now())/1000));const node=document.querySelector('#next-capture');if(node)node.textContent=model.monitor?.running?'采集中':Number.isFinite(next)?String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0'):'待连接';}
function renderMonitor(){const m=model.monitor||{},newCount=model.newEventCount||0;document.querySelector('#monitor-total').textContent=String(model.accountTotal??'—');document.querySelector('#monitor-complete').textContent=(model.cachedCount??0)+' / '+(model.accountTotal??'—');document.querySelector('#monitor-complete-note').textContent=model.complete?'条数已与平台汇总核对':'尚未完成全量采集';document.querySelector('#monitor-new').textContent=String(newCount);document.querySelector('#monitor-last').textContent=m.lastSuccessAt?new Date(m.lastSuccessAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'等待第一轮完整采集';document.querySelector('#monitor-message').textContent=m.error?.message||(model.historical?'正在查看已保存的历史日期。':m.running?'正在按顺序读取所有分页，成功后统一更新。':'已保存完整数据。新增按计划ID识别；首次完整采集只建立基准。');document.querySelector('#monitor-connection').textContent=m.bridgeConnected?'采集浏览器已连接':'采集浏览器未连接';document.querySelector('#monitor-warning').classList.toggle('warning',Boolean(m.error)||!model.complete);$('#new-plan').textContent=(query.onlyNew?'显示全部':'只看新增')+(newCount?'（'+newCount+'）':'');$('#new-plan').classList.toggle('active',Boolean(query.onlyNew));if(lastCycleSeen&&lastCycleSeen!==model.fetchedAt&&newCount)toast('采集已更新，最近发现'+newCount+'条计划');lastCycleSeen=model.fetchedAt;renderCountdown();}

function initializeLanInterface(){
 const icons={search:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>',columns:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16M15 4v16"/></svg>',refresh:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1"/></svg>',expand:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 4H4v5M15 4h5v5M4 15v5h5M20 15v5h-5"/></svg>'};
 let saved={};try{saved=JSON.parse(localStorage.getItem('qianchuan:1000000000000000:lan-ui:v1'))||{};}catch{}
 document.body.dataset.tableView=saved.view==='full'?'full':'data';
 document.body.dataset.density=saved.density==='comfortable'?'comfortable':'compact';
 document.body.classList.toggle('overview-collapsed',saved.collapsed===true);
 $('#search-button').innerHTML=icons.search;$('#search').placeholder='搜索计划名称或 ID';
 const clear=document.createElement('button');clear.id='clear-search';clear.type='button';clear.setAttribute('aria-label','清空搜索');clear.textContent='×';clear.hidden=true;clear.onclick=()=>{$('#search').value='';search();};document.querySelector('.search').insertBefore(clear,$('#search-button'));
 $('#search').addEventListener('input',()=>clear.hidden=!$('#search').value);
 $('#columns').innerHTML=icons.columns+'<span>指标设置</span>';$('#fullscreen').innerHTML=icons.expand;
 $('#table-columns').innerHTML=icons.columns+'<span>指标列</span>';document.querySelector('.table-actions').append($('#table-columns'));
 $('#reset').textContent='重置';$('#reset').title='重置搜索和筛选';
 $('#refresh').innerHTML=icons.refresh+'<span>刷新显示</span><span id="updated" class="sr-only">尚未更新</span>';$('#refresh').setAttribute('aria-label','刷新显示');
 document.querySelectorAll('.view-mode button[data-table-view]').forEach(button=>button.onclick=()=>{document.body.dataset.tableView=button.dataset.tableView;applyTableView();saveInterfacePreferences();});
 $('#density-toggle').onclick=()=>{document.body.dataset.density=document.body.dataset.density==='compact'?'comfortable':'compact';applyTableView();saveInterfacePreferences();};
 $('#overview-toggle').onclick=()=>{document.body.classList.toggle('overview-collapsed');applyTableView();saveInterfacePreferences();};
 $('#sync-toggle').onclick=()=>{const expanded=$('#sync-toggle').getAttribute('aria-expanded')==='true';$('#sync-toggle').setAttribute('aria-expanded',String(!expanded));$('#sync-details').hidden=expanded;};
 applyTableView();
}
function saveInterfacePreferences(){try{localStorage.setItem('qianchuan:1000000000000000:lan-ui:v1',JSON.stringify({view:document.body.dataset.tableView,density:document.body.dataset.density,collapsed:document.body.classList.contains('overview-collapsed')}));}catch{}}
function applyTableView(){
 const compact=document.body.dataset.tableView!=='full';
 document.querySelectorAll('.table-scroll thead tr').forEach(row=>[4,5,6,7].forEach(i=>row.children[i]?.classList.add('context-col')));
 document.querySelectorAll('#table-body tr:not(.total-row)').forEach(row=>{[4,5,6,7].forEach(i=>row.children[i]?.classList.add('context-col'));row.classList.toggle('row-selected',Boolean(row.querySelector('[data-select]')?.checked));});
 const summary=document.querySelector('.total-row td:nth-child(2)');if(summary)summary.colSpan=compact?3:7;
 document.querySelectorAll('.view-mode button[data-table-view]').forEach(button=>{const active=button.dataset.tableView===(compact?'data':'full');button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});
 const density=$('#density-toggle');if(density){density.textContent=document.body.dataset.density==='comfortable'?'紧凑行高':'舒适行高';density.setAttribute('aria-label',density.textContent);}
 const collapsed=document.body.classList.contains('overview-collapsed'),toggle=$('#overview-toggle');if(toggle){toggle.textContent=collapsed?'展开概览':'收起概览';toggle.setAttribute('aria-expanded',String(!collapsed));}
 const clear=$('#clear-search');if(clear)clear.hidden=!$('#search').value;
 $('#new-plan')?.setAttribute('aria-pressed',String(Boolean(query.onlyNew)));
 document.querySelectorAll('.plan-name').forEach(button=>button.title=button.textContent.trim());
 document.querySelectorAll('.table-scroll th[data-col] button').forEach(button=>button.title=button.textContent.trim());
 document.querySelectorAll('.metric').forEach(card=>{const heading=card.querySelector('h2');if(heading)heading.title=heading.textContent;});
}
function updateInterfaceStatus(data){
 const state=data.monitor||{},pill=$('#connection-pill'),strip=$('#sync-strip'),waiting=!state.bridgeConnected,error=Boolean(state.error)||waiting;
 strip.dataset.state=error?'warning':state.running?'loading':'ready';
 pill.textContent=waiting?'采集连接待恢复':state.running?'正在采集':state.error?'本轮更新失败':'采集连接正常';
 $('#sync-toggle').textContent=error?'查看原因':'采集说明';$('#sync-summary').textContent=error?'保留上次成功数据':'每 5 分钟自动采集';
 $('#next-label').textContent=waiting?'下次检查':'下次采集';
 $('#monitor-warning').classList.toggle('warning',!data.complete);$('#list-match-count').textContent=`当前匹配 ${data.total} 条`;
 $('#source-status').textContent=data.complete?'完整采集 · 操作需登录':'数据待补齐 · 操作需登录';strip.title=state.error?.message||'所有内网访客共享一份采集结果';applyTableView();
}
function showInterfaceError(error){
 const strip=$('#sync-strip');if(!strip)return;strip.dataset.state='warning';$('#connection-pill').textContent='页面同步失败';$('#sync-summary').textContent='已保留上次显示的数据';$('#monitor-message').textContent=error.message;$('#sync-toggle').textContent='查看原因';
 const range=$('#range-message');if(range){range.textContent='查询未更新：'+error.message+(model.from?'；仍显示 '+model.from+' 至 '+model.to:'');range.classList.add('error');}
}

function initializeDateRange(){
 for(const id of ['date-from','date-to']){$('#'+id).hidden=false;$('#'+id).max=getShanghaiDate();$('#'+id).oninput=$('#'+id).onchange=()=>{rangeDraftDirty=true;$('#range-preset').value='custom';$('#range-message').textContent='日期已修改，请点击查询。'+(model.from?'当前仍显示 '+model.from+' 至 '+model.to:'');$('#range-message').classList.remove('error');};}
 $('#date-from').value=appliedRange.from;$('#date-to').value=appliedRange.to;
 $('#range-preset').onchange=()=>{const chosen=datePreset($('#range-preset').value);if(chosen){$('#date-from').value=chosen.from;$('#date-to').value=chosen.to;submitDateRange();}};
 $('#apply-range').onclick=submitDateRange;
}
function getAppliedRange(){
 const current=getShanghaiDate();$('#date-from').max=current;$('#date-to').max=current;
 if(rangeMode!=='custom')appliedRange=datePreset(rangeMode,current);
 if(!rangeDraftDirty){$('#date-from').value=appliedRange.from;$('#date-to').value=appliedRange.to;}
 return appliedRange;
}
function submitDateRange(){
 try{const next=validateDateRange($('#date-from').value,$('#date-to').value);appliedRange=next;rangeMode=$('#range-preset').value;rangeDraftDirty=false;query.page=1;query.onlyNew=false;$('#range-message').classList.remove('error');poller.invalidate();}
 catch(error){$('#range-message').textContent=error.message;$('#range-message').classList.add('error');}
}
function showRangeLoading(value){
 const button=$('#apply-range');if(!button)return;button.disabled=value;button.textContent=value?'查询中…':'查询';
 if(value&&(model.from!==appliedRange.from||model.to!==appliedRange.to)){$('#range-message').textContent='正在查询 '+appliedRange.from+' 至 '+appliedRange.to+'…'+(model.from?' 暂时保留上次结果。':'');$('#range-message').classList.remove('error');}
}
function showAppliedRange(data){
 if(rangeDraftDirty)return;const range=$('#range-message');range.classList.toggle('error',Boolean(data.rangeQuery?.error));range.textContent='当前显示：'+data.from+' 至 '+data.to+(data.rangeQuery?.stale?' · 更新失败，保留该区间上次结果':' · 指标按此区间统计');
 if(data.rangeQuery){$('#sync-summary').textContent=data.rangeQuery.stale?'保留区间上次成功数据':'区间数据每5分钟刷新';$('#next-label').textContent='区间刷新';$('#monitor-message').textContent=data.rangeQuery.error?.message||'当前为所选日期区间的真实查询结果；今日新增计划监测仍在后台运行。';}
}

$('#batch-boost').onclick=()=>openBatchBoost({from:model.from||getAppliedRange().from,to:model.to||getAppliedRange().to,selectedIds:[...selectedPlans],notify:toast,onSuccess:()=>poller.invalidate()});
